const KEYWORDS = [
  { term: 'inteligencia artificial atendimento', nicho: 'ia-atendimento' },
  { term: 'n8n automacao', nicho: 'automacao' },
  { term: 'chatbot whatsapp brasil', nicho: 'whatsapp' },
  { term: 'agente ia vendas', nicho: 'vendas-ia' },
  { term: 'openai api novidades', nicho: 'llm' },
  { term: 'automacao marketing digital', nicho: 'marketing' }
];

return KEYWORDS.map(k => ({ json: k }));

const data = $('🧠 Agrupa e Filtra').first().json;

if (data.skip) {
  return [{ json: { send: false } }];
}

// Tentar pegar os resumos da IA (caso o nó da IA falhe, os resumos ficarão vazios)
let resumosIa = [];
try {
    const resp = $input.first().json;
    const aiText = resp.output || "[]";
    const cleaned = aiText.replace(/```json/g, '').replace(/```/g, '');
    resumosIa = JSON.parse(cleaned);
} catch(e) {
    // Falha ao parsear JSON da IA, fallback
}

let msg = '📰 *RADAR DE NOTÍCIAS*\n';
msg += '⏰ ' + new Date().toLocaleString('pt-BR') + '\n';
msg += '📊 ' + data.total_noticias + ' notícias inéditas\n\n';

const byNicho = {};
data.noticias.forEach(n => {
  if (!byNicho[n.nicho]) byNicho[n.nicho] = [];
  byNicho[n.nicho].push(n);
});

for (const [nicho, noticias] of Object.entries(byNicho)) {
  msg += '🏷️ *' + nicho.toUpperCase() + '*\n';
  noticias.forEach(n => {
    // Buscar resumo
    const res = resumosIa.find(r => r.link === n.link);

    let tagSentimento = '📢 *[TENDÊNCIA]* ';
    let textJustificativa = '';

    if (res) {
      if (res.categoria === 'oportunidade') {
        tagSentimento = '📈 *[OPORTUNIDADE]* ';
      } else if (res.categoria === 'risco') {
        tagSentimento = '⚠️ *[RISCO]* ';
      }
      if (res.justificativa) {
        textJustificativa = '\n    💡 _Impacto: ' + res.justificativa + '_';
      }
    }

    const textResumo = res && res.resumo ? '\n    🧠 _' + res.resumo + '_' : '';

    msg += '  • ' + tagSentimento + '*' + n.titulo + '*' + textResumo + textJustificativa + '\n    📎 ' + n.fonte + ' | 🔗 ' + n.link + '\n';
  });
  msg += '\n';
}

msg += '💡 _Essas notícias acabaram de sair do forno!_';

return [{ json: { send: true, message: msg, phone: '5522998908709', session: 'motoe-principal-bus' } }];

const results = [];
for (const item of $input.all()) {
  const xml = item.json.data || '';
  const items = xml.match(/<item>([\s\S]*?)<\/item>/g) || [];

  for (const entry of items) {
    const title = (entry.match(/<title>(.*?)<\/title>/) || [])[1] || '';
    const link = (entry.match(/<link>(.*?)<\/link>/) || [])[1] || '';
    const pubDate = (entry.match(/<pubDate>(.*?)<\/pubDate>/) || [])[1] || '';
    const source = (entry.match(/<source[^>]*>(.*?)<\/source>/) || [])[1] || '';

    const cleanLink = link.split('?')[0].trim();
    const cleanTitle = title.replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').trim();

    // Hash simples para o link (Base64)
    const hash = Buffer.from(cleanLink).toString('base64').replace(/=/g, '');

    if (!title || title.includes('CDATA')) continue;

    results.push({
      json: {
        titulo: cleanTitle,
        fonte: source.replace(/<[^>]+>/g, ''),
        link: cleanLink,
        hash: hash,
        data: pubDate,
        nicho: item.json.nicho || 'geral'
      }
    });
  }
}
return results;

const noticiasRaw = $('🧠 Extrai Notícias').all();
const redisChecks = $('🔌 Checar Redis Individual').all();
const results = [];

for (let i = 0; i < noticiasRaw.length; i++) {
    const noticia = noticiasRaw[i].json;
    const redisCheck = redisChecks[i].json.propertyName;

    // Se o redis retornou um valor, é porque a notícia já foi enviada
    if (redisCheck) continue;

    // Limita a 3 notícias por nicho
    if (results.filter(r => r.nicho === noticia.nicho).length >= 3) continue;

    results.push(noticia);
}

if (results.length === 0) {
    return [{ json: { skip: true, message: 'Nenhuma notícia nova encontrada' } }];
}

return [{ json: {
    skip: false,
    timestamp: new Date().toISOString(),
    total_noticias: results.length,
    noticias: results
} }];

const data = $('🧠 Agrupa e Filtra').first().json;
if (!data || data.skip) return [];

return data.noticias.map(n => ({
    json: {
        hash: n.hash,
        link: n.link
    }
}));
